//! PF-06 旧 owning API 的 safe Rust 静态 TLS 存储证明；只编译，不执行死锁风险路径。
#![forbid(unsafe_code)]
use diskgraph_ffi::{NativeService, NativeServiceError, NativeServiceOwner};
use std::cell::RefCell;

thread_local! {
    static OWNER: RefCell<Option<NativeServiceOwner>> = const { RefCell::new(None) };
}

pub fn store_owner(database: String) -> Result<(), NativeServiceError> {
    let (service, owner) = NativeService::new_with_owner(database)?;
    OWNER.with(|slot| *slot.borrow_mut() = Some(owner));
    drop(service);
    Ok(())
}
